public final class TenantClient {
    private static final ConcurrentMap<String, TenantClient> INSTANCES =
        new ConcurrentHashMap<>();
    private final String tenant;

    private TenantClient(String tenant) { this.tenant = tenant; }

    public static TenantClient forTenant(String tenant) {
        return INSTANCES.computeIfAbsent(tenant, TenantClient::new);
    }
}

